using Windows.Media.Ocr;
namespace LadderRecords;
[System.Runtime.Versioning.SupportedOSPlatform("windows10.0.19041")]
static class OcrOptimizationChecks
{
 static async Task<SoftwareBitmap> Legacy(Bitmap image,bool binary){if(binary){var bits=image.LockBits(new Rectangle(Point.Empty,image.Size),ImageLockMode.ReadWrite,PixelFormat.Format32bppArgb);try{var pixels=new byte[bits.Stride*image.Height];Marshal.Copy(bits.Scan0,pixels,0,pixels.Length);for(int y=0;y<image.Height;y++)for(int x=0;x<image.Width;x++){int offset=y*bits.Stride+x*4;var c=Color.FromArgb(pixels[offset+2],pixels[offset+1],pixels[offset]);byte value=c.R>=130&&c.G>=130&&c.B>=130&&c.GetSaturation()<.45?(byte)0:(byte)255;pixels[offset]=pixels[offset+1]=pixels[offset+2]=value;pixels[offset+3]=255;}Marshal.Copy(pixels,0,bits.Scan0,pixels.Length);}finally{image.UnlockBits(bits);}}using var ms=new MemoryStream();image.Save(ms,ImageFormat.Png);using var stream=new InMemoryRandomAccessStream();using(var writer=new DataWriter(stream)){writer.WriteBytes(ms.ToArray());await writer.StoreAsync();writer.DetachStream();}stream.Seek(0);var decoder=await BitmapDecoder.CreateAsync(stream);return await decoder.GetSoftwareBitmapAsync(BitmapPixelFormat.Bgra8,BitmapAlphaMode.Premultiplied);}
 static byte[] Pixels(SoftwareBitmap image){var buffer=new Windows.Storage.Streams.Buffer((uint)(image.PixelWidth*image.PixelHeight*4));image.CopyToBuffer(buffer);using var reader=DataReader.FromBuffer(buffer);var bytes=new byte[buffer.Length];reader.ReadBytes(bytes);return bytes;}
 public static async Task Run(){var rows=new List<object>();var engine=OcrEngine.TryCreateFromLanguage(new Windows.Globalization.Language("en-US"))??OcrEngine.TryCreateFromLanguage(new Windows.Globalization.Language("ko-KR"))??throw new Exception("OCR unavailable");foreach(var size in new[]{new Size(824,164),new Size(894,924)})foreach(bool binary in new[]{false,true}){using var image=new Bitmap(size.Width,size.Height);using(var g=Graphics.FromImage(image)){using var background=new LinearGradientBrush(new Rectangle(Point.Empty,size),Color.FromArgb(20,30,50),Color.FromArgb(90,30,70),45);g.FillRectangle(background,new Rectangle(Point.Empty,size));using var font=new Font("Arial",24,FontStyle.Bold,GraphicsUnit.Pixel);g.DrawString("RATE 98.54%",font,Brushes.White,20,20);g.DrawString("ROUND 3 HARD JUDGEMENT",font,Brushes.Yellow,20,80);g.FillRectangle(Brushes.DarkTurquoise,2,130,180,20);}using(var oldInput=new Bitmap(image))using(var oldImage=await Legacy(oldInput,binary))using(var newImage=OcrPixels.Create(image,binary)){if(!Pixels(oldImage).SequenceEqual(Pixels(newImage)))throw new Exception("OCR input pixels changed");var oldResult=await engine.RecognizeAsync(oldImage);var newResult=await engine.RecognizeAsync(newImage);if(oldResult.Text!=newResult.Text)throw new Exception("OCR text changed");}var oldTimes=new List<double>();var newTimes=new List<double>();for(int i=0;i<12;i++){using var oldInput=new Bitmap(image);var watch=Stopwatch.StartNew();using(var result=await Legacy(oldInput,binary)){}if(i>=2)oldTimes.Add(watch.Elapsed.TotalMilliseconds);watch.Restart();using(var result=OcrPixels.Create(image,binary)){}if(i>=2)newTimes.Add(watch.Elapsed.TotalMilliseconds);}rows.Add(new{width=size.Width,height=size.Height,binary,pixels_identical=true,ocr_text_identical=true,legacy_mean_ms=oldTimes.Average(),direct_mean_ms=newTimes.Average()});}File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"ocr-optimization-validation.json"),JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));}
}
